      + smoothstep(0.76, 0.83, wearNoise(dir * 31.0 + 17.1)) * 0.6;
    env += (uHorizon * 0.9 + uZenith * 0.4) * shard;
    env *= 1.0 - smoothstep(0.68, 0.78, wearNoise(dir * 9.0 + 41.0)) * 0.55;
