`,mD={name:"stainedGlass",glsl:pD,params:["density","lead","flash"],variants:[{name:"oceanglass",ramp:"oceanglass",knobs:{gloss:.05,rim:.11,sunGlare:.02,envGain:.16},params:[1,1,1]},{name:"rosewindow",ramp:"rosewindow",knobs:{gloss:.05,rim:.11,sunGlare:.03,envGain:.16},params:[1,1,1]},{name:"ivyglass",ramp:"ivyglass",knobs:{gloss:.05,rim:.11,sunGlare:.02,envGain:.16},params:[1,1,1]},{name:"lapispane",ramp:"lapispane",knobs:{gloss:.04,rim:.14,sunGlare:.02,envGain:.18},params:[1,1.25,.6]}],slots:{surface:`
